// Compute a simple qualification score + status from the trigger's qualification_answers.
const trigger = $('When Executed by Another Workflow').first().json;
const answers = trigger.qualification_answers || {};
const contactId = $json.id; // from Upsert Contact

let score = 0;
if (answers.budget) score += 25;
if (answers.timeline && /\b(week|month|asap|now|soon)\b/i.test(answers.timeline)) score += 25;
if (answers.property_type) score += 15;
if (answers.intent_signal) score += 20;
if (trigger.contact?.email) score += 10;
if (trigger.contact?.phone) score += 5;

let status = 'QUALIFYING';
if (score >= 70) status = 'HOT';
// 'WARM', not 'QUALIFIED': leads.status only allows NEW / QUALIFYING / HOT /
// WARM / COLD / CONVERTED / LOST (leads_status_check). 'QUALIFIED' made every
// 40-69 lead fail to save, so mid-scoring leads were silently lost.
else if (score >= 40) status = 'WARM';

return [{
  json: {
    tenant_id: trigger.tenant_id,
    contact_id: contactId,
    status,
    score,
    qualification_answers: answers
  }
}];

// Normalize output shape for the Main Agent's tool_result formatting.
// IMPORTANT: return contact_id so the agent can pass a real UUID to
// book_appointment. Read it from Score Lead (which carries the upserted
// contact id), falling back to Upsert Lead if needed.
const leadResult = $('Upsert Lead').first().json;
const scored = $('Score Lead').first().json;
const trigger = $('When Executed by Another Workflow').first().json;

return [{
  json: {
    success: true,
    lead_id: leadResult.id,
    contact_id: scored.contact_id || null,
    status: leadResult.status,
    score: leadResult.score,
    contact_email: trigger.contact?.email || null
  }
}];
